<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { setTheme } from 'mdui/functions/setTheme.js';
import Icon from './Icon.vue';
import { api, APIError, type Account, type Browse, type FileItem, type Settings, type State, type Task } from './api';
import { t, statusLabel, size, date } from './messages';
const routes=['downloads','resolve','accounts','settings'] as const;
type Route=typeof routes[number];
const icons=['download--outlined','link--outlined','cloud--outlined','settings--outlined'];
const route=ref<Route>('downloads'), ready=ref(false), loggedIn=ref(false), online=ref(false), busy=ref(''), error=ref(''), notice=ref(''), name=ref(t('brand') as string);
const state=ref<State>(), username=ref('admin'), password=ref('');
let stream:EventSource|undefined, noticeTimer:ReturnType<typeof setTimeout>|undefined;
const settings=reactive<Settings>({name:'云析',concurrency:2,connections:4,speed_limit:0,default_dir:'',resume_on_restart:true,theme:'auto'}), settingsDirty=ref(false), limitMiB=ref(0);
const link=ref(''), passcode=ref(''), accountID=ref(''), directory=ref(''), browse=ref<Browse>(), selectedFiles=ref<string[]>([]), trail=ref<{id:string;name:string}[]>([]);
const query=ref(''), filter=ref('all'), selectedTasks=ref<string[]>([]), accountOpen=ref(false), accountForm=reactive({id:'',platform:'quark',name:'',credential:''});
const currentPassword=ref(''), newPassword=ref(''), repeatPassword=ref('');
const confirmOpen=ref(false), confirmType=ref(''), confirmID=ref(''), deleteFile=ref(false);
const directoryOpen=ref(false), directoryPath=ref(''), directories=ref<string[]>([]), newFolder=ref('');
const val=(e:Event)=>String((e.target as HTMLInputElement).value);
const checked=(e:Event)=>Boolean((e.target as HTMLInputElement).checked);
const platformIcons: Record<string,string>={quark:'/icons/quark.png',uc:'/icons/uc.png',pan123:'/icons/pan123.png',bilibili:'/icons/bilibili.png'};
const platformName=(id:string)=>state.value?.platforms.find(x=>x.id===id)?.name||(id==='direct'?'HTTP':id);
const tasks=computed(()=>state.value?.tasks||[]), accounts=computed(()=>state.value?.accounts||[]);
const running=computed(()=>tasks.value.filter(x=>['resolving','downloading','merging','pausing'].includes(x.status)));
const filtered=computed(()=>tasks.value.filter(x=>(filter.value==='all'||filter.value==='active'&&['queued','resolving','downloading','merging','pausing'].includes(x.status)||filter.value==='completed'&&x.status==='completed'||filter.value==='failed'&&['failed','waiting_account'].includes(x.status))&&x.name.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
const totalSpeed=computed(()=>tasks.value.reduce((n,x)=>n+x.speed,0));
const canPause=(x:Task)=>['queued','resolving','downloading'].includes(x.status);
const canResume=(x:Task)=>['paused','failed','waiting_account'].includes(x.status);
const canRemove=(x:Task)=>!['resolving','downloading','merging','pausing'].includes(x.status);
const percent=(x:Task)=>x.size>0?Math.min(1,x.downloaded/x.size):undefined;
function go(r:Route){route.value=r;location.hash=r;error.value=''}
function readHash(){const h=location.hash.slice(1) as Route;route.value=routes.includes(h)?h:'downloads'}
function apply(v:State){state.value=v;name.value=v.settings.name;document.title=`${name.value} · NAS`;if(!settingsDirty.value){Object.assign(settings,v.settings);limitMiB.value=v.settings.speed_limit/1048576}setTheme(v.settings.theme as 'auto'|'light'|'dark')}
function announce(message:string){notice.value=message;if(noticeTimer)clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',5000)}
function showError(e:unknown){error.value=e instanceof Error?e.message:t('networkError');if(e instanceof APIError&&e.status===401){loggedIn.value=false;stream?.close()}}
async function run(key:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=key;error.value='';try{await fn()}catch(e){showError(e)}finally{busy.value=''}}
async function refresh(){apply(await api<State>('/state'));online.value=true}
function connect(){stream?.close();stream=new EventSource('/api/events');stream.addEventListener('state',e=>{try{apply(JSON.parse((e as MessageEvent).data));online.value=true}catch{online.value=false}});stream.addEventListener('expired',()=>{stream?.close();loggedIn.value=false;online.value=false;error.value='登录已过期，请重新登录。'});stream.onerror=()=>{stream?.close();online.value=false}}
async function reconnect(){await run('refresh',async()=>{await refresh();connect()})}
async function login(){await run('login',async()=>{await api('/auth/login','POST',{username:username.value,password:password.value});password.value='';loggedIn.value=true;await refresh();directory.value=settings.default_dir;connect()})}
async function logout(){await run('logout',async()=>{await api('/auth/logout','POST',{});stream?.close();loggedIn.value=false;online.value=false;state.value=undefined})}
async function parse(cloud=false,id=accountID.value){await run('parse',async()=>{const v=await api<Browse>('/resolve','POST',{text:link.value,password:passcode.value,account_id:id,cloud});browse.value=v;selectedFiles.value=[];trail.value=[{id:'0',name:v.title||t('rootDirectory')}];directory.value=settings.default_dir;go('resolve')})}
async function openFolder(item:FileItem){await run('browse',async()=>{const v=await api<Browse>('/browse','POST',{session_id:browse.value!.session_id,parent:item.id,page:1});browse.value=v;selectedFiles.value=[];trail.value.push({id:item.id,name:item.name})})}
async function backFolder(){if(trail.value.length<2)return;await run('browse',async()=>{const parent=trail.value.at(-2)!;browse.value=await api<Browse>('/browse','POST',{session_id:browse.value!.session_id,parent:parent.id,page:1});trail.value.pop();selectedFiles.value=[]})}
async function loadMore(){await run('more',async()=>{const v=await api<Browse>('/browse','POST',{session_id:browse.value!.session_id,parent:browse.value!.parent,page:browse.value!.page+1});const seen=new Set(browse.value!.items.map(x=>x.id));browse.value={...v,items:[...browse.value!.items,...v.items.filter(x=>!seen.has(x.id))]}})}
function toggle(list:string[],id:string,on:boolean){return on?[...new Set([...list,id])]:list.filter(x=>x!==id)}
async function enqueue(){await run('enqueue',async()=>{await api('/tasks','POST',{session_id:browse.value!.session_id,item_ids:selectedFiles.value,directory:directory.value});selectedFiles.value=[];await refresh();go('downloads');announce(t('queuedSuccess'))})}
async function action(id:string,action:string){await run(id,async()=>{await api(`/tasks/${id}/action`,'POST',{action,delete_file:false});await refresh()})}
async function bulk(actionName:string){await run('bulk',async()=>{for(const task of tasks.value.filter(x=>selectedTasks.value.includes(x.id)&&(actionName==='pause'?canPause(x):canResume(x)))){await api(`/tasks/${task.id}/action`,'POST',{action:actionName,delete_file:false})}selectedTasks.value=[];await refresh()})}
function ask(type:string,id:string){confirmType.value=type;confirmID.value=id;deleteFile.value=false;confirmOpen.value=true}
async function confirmAction(){await run('confirm',async()=>{if(confirmType.value==='account'){await api(`/accounts/${confirmID.value}`,'DELETE')}else{await api(`/tasks/${confirmID.value}/action`,'POST',{action:confirmType.value,delete_file:deleteFile.value})}confirmOpen.value=false;await refresh();announce(t('operationSuccess'))})}
function editAccount(a?:Account){Object.assign(accountForm,{id:a?.id||'',platform:a?.platform||'quark',name:a?.name||'',credential:''});accountOpen.value=true}
async function saveAccount(){await run('account-save',async()=>{await api('/accounts','POST',accountForm);accountForm.credential='';accountOpen.value=false;await refresh();announce(t('accountSaved'))})}
async function checkAccount(id:string){await run(id,async()=>{await api(`/accounts/${id}/check`,'POST',{});await refresh()})}
function dirty(){settingsDirty.value=true}
async function saveSettings(){await run('settings',async()=>{const saved=await api<Settings>('/settings','PUT',{...settings,speed_limit:Math.round(limitMiB.value*1048576)});settingsDirty.value=false;Object.assign(settings,saved);await refresh();announce(t('settingsSaved'))})}
async function changePassword(){await run('password',async()=>{if(newPassword.value!==repeatPassword.value)throw new Error(t('passwordMismatch'));await api('/auth/password','POST',{current:currentPassword.value,password:newPassword.value});currentPassword.value='';newPassword.value='';repeatPassword.value='';stream?.close();loggedIn.value=false;announce(t('operationSuccess'))})}
async function readDirectories(path:string){const v=await api<{path:string;directories:string[]}>('/directories?path='+encodeURIComponent(path));directoryPath.value=v.path;directories.value=v.directories}
async function chooseDirectory(){await run('directory',async()=>{await readDirectories(directory.value);directoryOpen.value=true})}
async function navigateDirectory(path:string){await run('directory',()=>readDirectories(path))}
async function createFolder(){await run('folder',async()=>{if(!newFolder.value||/[\\/]/.test(newFolder.value))throw new Error('请输入单层文件夹名称。');await api('/directories','POST',{path:[directoryPath.value,newFolder.value].filter(Boolean).join('/')});newFolder.value='';await readDirectories(directoryPath.value)})}
watch(route,()=>{selectedTasks.value=[]});
onMounted(async()=>{readHash();window.addEventListener('hashchange',readHash);try{const s=await api<{authenticated:boolean;name:string}>('/auth/session');name.value=s.name;document.title=`${s.name} · NAS`;loggedIn.value=s.authenticated;if(s.authenticated){await refresh();directory.value=settings.default_dir;connect()}}catch(e){showError(e)}finally{ready.value=true}});
onUnmounted(()=>{stream?.close();if(noticeTimer)clearTimeout(noticeTimer);window.removeEventListener('hashchange',readHash)});
</script>

<template>
 <div v-if="!ready" class="initializing" role="status"><mdui-circular-progress/><p>{{t('initializing')}}</p></div>
 <main v-else-if="!loggedIn" class="login-page">
  <form class="login-panel" @submit.prevent="login">
   <div class="brand"><img src="/icons/yunx.png" alt="" width="36" height="36"/><span>{{name}}</span></div>
   <h1>{{t('loginTitle')}}</h1><p class="muted">{{t('loginDescription')}}</p>
   <div v-if="error" class="alert error" role="alert">{{error}}</div>
   <mdui-text-field :label="t('username')" :value="username" autocomplete="username" required @input="username=val($event)"/>
   <mdui-text-field :label="t('password')" :value="password" type="password" autocomplete="current-password" toggle-password required @input="password=val($event)"/>
   <mdui-button type="submit" :loading="busy==='login'" :disabled="!!busy">{{t('login')}}</mdui-button>
   <p class="helper">{{t('loginHelp')}}</p>
  </form>
 </main>
 <div v-else class="app-shell">
  <aside class="sidebar">
   <a class="brand" href="#downloads"><img src="/icons/yunx.png" alt="" width="32" height="32"/><span>{{name}}</span></a>
   <p class="workspace-label">{{t('workspace')}}</p>
   <nav aria-label="主导航"><a v-for="(item,i) in routes" :key="item" :href="'#'+item" :class="{active:route===item}" :aria-current="route===item?'page':undefined" @click="go(item)"><Icon :name="icons[i]!"/><span>{{t(item)}}</span><span v-if="item==='downloads'&&tasks.length" class="nav-count">{{tasks.length}}</span></a></nav>
   <div class="sidebar-bottom"><div class="connection"><span class="status-dot" :class="{offline:!online}"></span>{{online?t('connected'):t('disconnected')}}</div><p>{{t('version')}} {{state?.version||'0.1.0'}}</p><mdui-button variant="text" @click="logout" :disabled="!!busy"><Icon slot="icon" name="logout"/>{{t('logout')}}</mdui-button></div>
  </aside>
  <main class="main-content">
   <header class="page-heading"><div><h1>{{t(route)}}</h1><p class="page-description">{{t(route==='downloads'?'tasksDescription':route==='resolve'?'resolveDescription':route==='accounts'?'accountsDescription':'settingsDescription')}}</p></div><div class="heading-actions"><mdui-button-icon v-control-label="t('refresh')" :disabled="!!busy" @click="reconnect"><Icon name="refresh"/></mdui-button-icon><mdui-button v-if="route==='downloads'" @click="go('resolve')"><Icon slot="icon" name="add"/>{{t('newDownload')}}</mdui-button><mdui-button v-if="route==='accounts'" @click="editAccount()"><Icon slot="icon" name="add"/>{{t('addAccount')}}</mdui-button></div></header>
   <div v-if="!online" class="alert offline-alert" role="status"><span>{{t('offline')}}</span><mdui-button variant="text" @click="reconnect" :disabled="!!busy">{{t('reconnect')}}</mdui-button></div>
   <div v-if="error" class="alert error" role="alert"><Icon name="error-outline"/><span>{{error}}</span><mdui-button-icon v-control-label="t('close')" @click="error=''"><Icon name="close"/></mdui-button-icon></div>
   <template v-if="route==='downloads'">
    <section class="summary-strip" aria-label="下载概况"><div><span>{{t('totalTasks')}}</span><strong>{{tasks.length}}</strong></div><div><span>{{t('running')}}</span><strong>{{running.length}}</strong></div><div><span>{{t('totalSpeed')}}</span><strong>{{size(totalSpeed)}}<small>/s</small></strong></div><div><span>{{t('diskAvailable')}}</span><strong>{{size(state?.disk.available)}}</strong></div></section>
    <section class="task-panel surface">
     <div class="task-toolbar"><div class="filters" role="group" aria-label="任务筛选"><button v-for="key in ['all','active','completed','failed'] as const" :key="key" :class="{selected:filter===key}" :aria-pressed="filter===key" @click="filter=key">{{t(key)}}</button></div><mdui-text-field class="task-search" :label="t('searchTasks')" :value="query" clearable @input="query=val($event)"/></div>
     <div v-if="selectedTasks.length" class="bulk-toolbar"><span>{{t('selected')}} {{selectedTasks.length}}</span><mdui-button variant="text" :disabled="!!busy||!online" @click="bulk('pause')">{{t('pauseSelected')}}</mdui-button><mdui-button variant="text" :disabled="!!busy||!online" @click="bulk('resume')">{{t('resumeSelected')}}</mdui-button><mdui-button variant="text" @click="selectedTasks=[]">{{t('cancel')}}</mdui-button></div>
     <div v-if="!filtered.length" class="empty-state"><Icon name="download--outlined"/><h2>{{tasks.length?t('noResults'):t('emptyTasks')}}</h2><p>{{tasks.length?t('noResultsBody'):t('emptyTasksBody')}}</p><mdui-button v-if="!tasks.length" @click="go('resolve')"><Icon slot="icon" name="add"/>{{t('newDownload')}}</mdui-button></div>
     <div v-else class="task-table" role="table" aria-label="下载任务"><div class="task-row table-head" role="row"><mdui-checkbox v-control-label="t('allSelected')" :checked="filtered.every(x=>selectedTasks.includes(x.id))" @change="selectedTasks=checked($event)?filtered.map(x=>x.id):[]"/><span role="columnheader">{{t('fileName')}}</span><span role="columnheader">{{t('progress')}}</span><span role="columnheader" class="numeric">{{t('speed')}}</span><span role="columnheader" class="action-heading">{{t('actions')}}</span></div>
      <div v-for="task in filtered" :key="task.id" class="task-row" role="row" :data-task-id="task.id"><mdui-checkbox v-control-label="'选择 '+task.name" :checked="selectedTasks.includes(task.id)" @change="selectedTasks=toggle(selectedTasks,task.id,checked($event))"/><div class="file-cell" role="cell"><Icon name="description--outlined"/><div><strong class="file-title" :title="task.name">{{task.name}}</strong><span class="file-meta">{{platformName(task.platform)}} <span aria-hidden="true">·</span> /downloads/{{task.directory}}</span><p v-if="task.error" class="task-error">{{task.error}}</p></div></div><div class="progress-cell" role="cell"><div class="progress-label"><span class="status-label" :class="task.status">{{statusLabel(task.status)}}</span><span class="numeric">{{size(task.downloaded)}} / {{task.size>0?size(task.size):t('unknownSize')}}</span></div><mdui-linear-progress v-if="['downloading','resolving','paused','pausing','queued'].includes(task.status)" :value="percent(task)" :aria-label="task.name+' '+t('progress')"/></div><span class="speed-cell numeric" role="cell">{{task.speed>0?size(task.speed)+'/s':'—'}}</span><div class="task-actions" role="cell"><mdui-button-icon v-if="canPause(task)" v-control-label="t('pause')+' '+task.name" :disabled="!!busy||!online" @click="action(task.id,'pause')"><Icon name="pause"/></mdui-button-icon><mdui-button-icon v-if="canResume(task)" v-control-label="t('resume')+' '+task.name" :disabled="!!busy||!online" @click="action(task.id,'resume')"><Icon name="play-arrow"/></mdui-button-icon><mdui-button-icon v-if="task.has_file" :href="'/api/tasks/'+task.id+'/file'" v-control-label="t('downloadToDevice')+' '+task.name"><Icon name="download--outlined"/></mdui-button-icon><mdui-button-icon v-if="canRemove(task)" v-control-label="t('remove')+' '+task.name" :disabled="!!busy||!online" @click="ask('delete',task.id)"><Icon name="close"/></mdui-button-icon><mdui-button-icon v-else-if="task.status!=='merging'" v-control-label="t('stop')+' '+task.name" :disabled="!!busy||!online" @click="ask('cancel',task.id)"><Icon name="close"/></mdui-button-icon></div></div>
     </div>
    </section>
    <details class="activity surface"><summary>{{t('logTitle')}}<span class="muted">{{state?.events.length||0}}</span></summary><p v-if="!state?.events.length" class="muted">{{t('logEmpty')}}</p><ol v-else><li v-for="event in state?.events.slice(0,30)" :key="event.id"><time :datetime="event.created_at">{{date(event.created_at)}}</time><span>{{event.message}}</span></li></ol></details>
   </template>
   <template v-if="route==='resolve'">
    <form class="surface resolve-form" @submit.prevent="parse()"><mdui-text-field :label="t('link')" :placeholder="t('linkPlaceholder')" :value="link" required autosize rows="2" @input="link=val($event)"/><div class="form-row"><mdui-text-field :label="t('passcode')" :value="passcode" @input="passcode=val($event)"/><mdui-select :label="t('useAccount')" :value="accountID" @change="accountID=val($event)"><mdui-menu-item value="">{{t('guest')}}</mdui-menu-item><mdui-menu-item v-for="a in accounts" :key="a.id" :value="a.id">{{platformName(a.platform)}} · {{a.name}}</mdui-menu-item></mdui-select><mdui-button type="submit" :loading="busy==='parse'" :disabled="!!busy||!online"><Icon slot="icon" name="link--outlined"/>{{busy==='parse'?t('parsing'):t('parse')}}</mdui-button></div><p class="helper">{{t('supported')}}</p></form>
    <section class="surface file-browser"><div v-if="!browse" class="empty-state"><Icon name="folder--outlined"/><h2>{{t('parseFirst')}}</h2><p>{{t('parseFirstBody')}}</p></div><template v-else><div class="browser-heading"><mdui-button-icon :disabled="trail.length<2||!!busy" v-control-label="t('back')" @click="backFolder"><Icon name="arrow-back"/></mdui-button-icon><h2 :title="trail.map(x=>x.name).join(' / ')">{{trail.at(-1)?.name}}</h2><span class="muted">{{browse.items.length}} {{t('files')}}</span></div><div class="browser-select"><mdui-checkbox :checked="!!browse.items.length&&browse.items.every(x=>selectedFiles.includes(x.id))" @change="selectedFiles=checked($event)?browse!.items.map(x=>x.id):[]">{{t('allSelected')}}</mdui-checkbox><span class="muted">{{t('selected')}} {{selectedFiles.length}}</span></div><p v-if="!browse.items.length" class="empty-folder">{{t('emptyFolder')}}</p><div v-for="file in browse.items" :key="file.id" class="browser-row"><mdui-checkbox v-control-label="'选择 '+file.name" :checked="selectedFiles.includes(file.id)" @change="selectedFiles=toggle(selectedFiles,file.id,checked($event))"/><Icon :name="file.directory?'folder--outlined':'description--outlined'"/><button v-if="file.directory" class="folder-link" :disabled="!!busy" @click="openFolder(file)">{{file.name}}</button><span v-else class="browser-name">{{file.name}}</span><span class="numeric muted">{{file.directory?t('folder'):size(file.size)}}</span></div><div v-if="browse.more" class="load-more"><mdui-button variant="text" :disabled="!!busy" @click="loadMore">{{t('loadMore')}}</mdui-button></div><div class="queue-bar"><div class="directory-field"><mdui-text-field :label="t('saveDirectory')" prefix="/downloads/" :value="directory" @input="directory=val($event)"/><mdui-button-icon v-control-label="t('directoryButton')" @click="chooseDirectory"><Icon name="folder--outlined"/></mdui-button-icon></div><mdui-button :disabled="!selectedFiles.length||!!busy||!online" :loading="busy==='enqueue'" @click="enqueue"><Icon slot="icon" name="download--outlined"/>{{t('addToQueue')}} ({{selectedFiles.length}})</mdui-button></div></template></section>
   </template>
   <template v-if="route==='accounts'"><div class="accounts-note"><Icon name="shield--outlined"/><span>{{t('privacy')}}</span></div><section class="surface account-list"><div v-if="!accounts.length" class="empty-state"><Icon name="cloud--outlined"/><h2>{{t('noAccounts')}}</h2><p>{{t('noAccountsBody')}}</p><mdui-button @click="editAccount()">{{t('addAccount')}}</mdui-button></div><article v-for="a in accounts" :key="a.id" class="account-row"><div class="platform-mark"><img v-if="platformIcons[a.platform]" :src="platformIcons[a.platform]" alt="" width="28" height="28"/><Icon v-else name="cloud--outlined"/></div><div class="account-info"><h2>{{a.name}}</h2><p class="muted">{{platformName(a.platform)}}<template v-if="a.nickname"> · {{a.nickname}}</template></p><p class="helper">{{a.message||t('accountUnchecked')}}</p></div><span class="status-label" :class="a.status">{{statusLabel(a.status)}}</span><div class="account-actions"><mdui-button variant="text" :loading="busy===a.id" :disabled="!!busy||!online" @click="checkAccount(a.id)">{{t('check')}}</mdui-button><mdui-button v-if="state?.platforms.find(p=>p.id===a.platform)?.cloud" variant="text" :disabled="!!busy||!online" @click="parse(true,a.id)">{{t('browseCloud')}}</mdui-button><mdui-button variant="text" @click="editAccount(a)">{{t('edit')}}</mdui-button><mdui-button-icon v-control-label="t('deleteAccount')+' '+a.name" :disabled="!!busy||!online" @click="ask('account',a.id)"><Icon name="close"/></mdui-button-icon></div></article></section></template>
   <template v-if="route==='settings'"><form class="settings-form" @submit.prevent="saveSettings"><section class="surface settings-section"><div class="section-description"><h2>{{t('general')}}</h2><p>{{t('generalHelp')}}</p></div><div class="settings-fields"><mdui-text-field :label="t('instanceName')" :value="settings.name" maxlength="60" required @input="settings.name=val($event);dirty()"/><mdui-select :label="t('theme')" :value="settings.theme" @change="settings.theme=val($event);dirty()"><mdui-menu-item v-for="v in ['auto','light','dark'] as const" :key="v" :value="v">{{t(v)}}</mdui-menu-item></mdui-select></div></section><section class="surface settings-section"><div class="section-description"><h2>{{t('downloadSettings')}}</h2><p>{{t('downloadHelp')}}</p></div><div class="settings-fields"><mdui-text-field :label="t('saveDirectory')" prefix="/downloads/" :value="settings.default_dir" :helper="t('directoryHint')" @input="settings.default_dir=val($event);dirty()"/><div class="form-row"><mdui-text-field :label="t('concurrency')" type="number" min="1" max="8" required :value="String(settings.concurrency)" @input="settings.concurrency=Number(val($event));dirty()"/><mdui-text-field :label="t('connections')" type="number" min="1" max="32" required :value="String(settings.connections)" @input="settings.connections=Number(val($event));dirty()"/></div><mdui-text-field :label="t('limit')" type="number" min="0" step="any" required :value="String(limitMiB)" :helper="t('limitHint')" @input="limitMiB=Number(val($event));dirty()"/><label class="switch-field"><div><strong>{{t('resumeRestart')}}</strong><p class="helper">{{t('resumeRestartHelp')}}</p></div><mdui-switch v-control-label="t('resumeRestart')" :checked="settings.resume_on_restart" @change="settings.resume_on_restart=checked($event);dirty()"/></label></div></section><div class="settings-submit"><mdui-button type="submit" :disabled="!!busy||!online||!settingsDirty" :loading="busy==='settings'">{{t('saveSettings')}}</mdui-button></div></form><form class="surface settings-section password-section" @submit.prevent="changePassword"><div class="section-description"><h2>{{t('passwordTitle')}}</h2><p>{{t('passwordHelp')}}</p></div><div class="settings-fields"><mdui-text-field :label="t('currentPassword')" type="password" autocomplete="current-password" :value="currentPassword" required @input="currentPassword=val($event)"/><mdui-text-field :label="t('newPassword')" type="password" autocomplete="new-password" minlength="12" :value="newPassword" required @input="newPassword=val($event)"/><mdui-text-field :label="t('repeatPassword')" type="password" autocomplete="new-password" :value="repeatPassword" required @input="repeatPassword=val($event)"/><mdui-button type="submit" variant="outlined" :disabled="!!busy||!online">{{t('changePassword')}}</mdui-button></div></form><mdui-button class="mobile-logout" variant="text" :disabled="!!busy" @click="logout"><Icon slot="icon" name="logout"/>{{t('logout')}}</mdui-button></template>
  </main>
  <nav class="mobile-nav" aria-label="移动导航"><a v-for="(item,i) in routes" :key="item" :href="'#'+item" :class="{active:route===item}" :aria-current="route===item?'page':undefined" @click="go(item)"><Icon :name="icons[i]!"/><span>{{t(item)}}</span></a></nav>
 </div>
 <mdui-dialog :open="accountOpen" :headline="accountForm.id?t('editAccount'):t('addAccount')" close-on-overlay-click close-on-esc @closed="accountOpen=false"><form id="account-form" class="dialog-form" @submit.prevent="saveAccount"><mdui-select :label="t('platform')" :disabled="!!accountForm.id" :value="accountForm.platform" @change="accountForm.platform=val($event)"><mdui-menu-item v-for="p in state?.platforms" :key="p.id" :value="p.id">{{p.name}}</mdui-menu-item></mdui-select><mdui-text-field :label="t('accountName')" :value="accountForm.name" required maxlength="80" @input="accountForm.name=val($event)"/><mdui-text-field :label="t('credential')" type="password" toggle-password autocomplete="off" :value="accountForm.credential" :required="!accountForm.id" :helper="accountForm.id?t('credentialKeep'):t('credentialHint')" @input="accountForm.credential=val($event)"/><p v-if="error&&accountOpen" class="inline-error" role="alert">{{error}}</p></form><mdui-button slot="action" variant="text" @click="accountOpen=false">{{t('cancel')}}</mdui-button><mdui-button slot="action" form="account-form" type="submit" :disabled="!!busy" :loading="busy==='account-save'">{{t('save')}}</mdui-button></mdui-dialog>
 <mdui-dialog :open="confirmOpen" :headline="confirmType==='account'?t('accountDeleteTitle'):confirmType==='delete'?t('deleteTitle'):t('cancelTitle')" close-on-esc @closed="confirmOpen=false"><p>{{confirmType==='account'?t('accountDeleteHelp'):confirmType==='delete'?t('deleteHelp'):t('cancelHelp')}}</p><template v-if="confirmType==='delete'"><mdui-checkbox :checked="deleteFile" @change="deleteFile=checked($event)">{{t('deleteFile')}}</mdui-checkbox><p v-if="deleteFile" class="inline-error">{{t('deleteFileHelp')}}</p></template><p v-if="error&&confirmOpen" class="inline-error" role="alert">{{error}}</p><mdui-button slot="action" variant="text" @click="confirmOpen=false">{{t('cancel')}}</mdui-button><mdui-button slot="action" :disabled="!!busy" @click="confirmAction">{{t('confirm')}}</mdui-button></mdui-dialog>
 <mdui-dialog :open="directoryOpen" :headline="t('selectDirectory')" close-on-esc @closed="directoryOpen=false"><div class="directory-browser"><div class="directory-current"><mdui-button-icon v-control-label="t('back')" :disabled="!directoryPath||!!busy" @click="navigateDirectory(directoryPath.split('/').slice(0,-1).join('/'))"><Icon name="arrow-back"/></mdui-button-icon><span>/downloads/{{directoryPath}}</span></div><button v-for="d in directories" :key="d" class="directory-option" :disabled="!!busy" @click="navigateDirectory(d)"><Icon name="folder--outlined"/>{{d.split('/').at(-1)}}</button><p v-if="!directories.length" class="muted">{{t('emptyFolder')}}</p><form class="form-row" @submit.prevent="createFolder"><mdui-text-field :label="t('folderName')" :value="newFolder" required @input="newFolder=val($event)"/><mdui-button type="submit" variant="text" :disabled="!!busy">{{t('newFolder')}}</mdui-button></form><p v-if="error&&directoryOpen" class="inline-error" role="alert">{{error}}</p></div><mdui-button slot="action" variant="text" @click="directoryOpen=false">{{t('cancel')}}</mdui-button><mdui-button slot="action" @click="directory=directoryPath;directoryOpen=false">{{t('useDirectory')}}</mdui-button></mdui-dialog>
 <div v-if="notice" class="toast" role="status">{{notice}}</div>
</template>
